from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                grid[yy][xx] == background and not seen[yy][xx]):
                            seen[yy][xx] = True
                            q.append((yy, xx))

            min_r = min(y for y, x in cells)
            max_r = max(y for y, x in cells)
            min_c = min(x for y, x in cells)
            max_c = max(x for y, x in cells)
            if len(cells) != (max_r - min_r + 1) * (max_c - min_c + 1):
                continue

            # A rectangular background component is a cavity when each side is
            # bordered by the foreground or by the edge of the grid.
            # Allow one grid edge to complete an outline, as in the demonstrations,
            # but do not treat a corner region bounded by two image edges as a cavity.
            border_sides = sum((min_r == 0, max_r == h - 1, min_c == 0, max_c == w - 1))
            enclosed = border_sides <= 1
            if border_sides and min(max_r - min_r + 1, max_c - min_c + 1) < 2:
                enclosed = False
            if min_r > 0:
                enclosed &= all(grid[min_r - 1][x] != background
                                for x in range(min_c, max_c + 1))
            if max_r < h - 1:
                enclosed &= all(grid[max_r + 1][x] != background
                                for x in range(min_c, max_c + 1))
            if min_c > 0:
                enclosed &= all(grid[y][min_c - 1] != background
                                for y in range(min_r, max_r + 1))
            if max_c < w - 1:
                enclosed &= all(grid[y][max_c + 1] != background
                                for y in range(min_r, max_r + 1))
            if enclosed:
                for y, x in cells:
                    out[y][x] = 4
    return out
